def find_solutions(limit):
    solutions = []
    primes = []
    is_prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False

    def solve(index, current_sum, current_n):
        if current_sum == 1:
            solutions.append(current_n)
            return
        if current_sum > 1 or index >= len(primes):
            return

        p = primes[index]
        # Try all possible powers a of p
        for a in range(1, p):
            new_n = current_n * (p**a)
            if new_n > limit:
                break
            solve(index + 1, current_sum + a/p, new_n)

    # Wait, the current_sum = 1 condition must be exactly 1.
    # Since we're dealing with fractions, let's use fractions.
    from fractions import Fraction

    def solve_fractions(index, current_sum, current_n):
        if current_sum == 1:
            solutions.append(current_n)
            return
        if current_sum > 1 or index >= len(primes):
            return

        p = primes[index]
        for a in range(1, p):
            new_n = current_n * (p**a)
            if new_n > limit:
                break
            solve_fractions(index + 1, current_sum + Fraction(a, p), new_n)

    solve_fractions(0, Fraction(0), 1)
    return sorted(list(set(solutions)))

print(find_solutions(4000))

